outputs = ['dg', 'zhuvacuhz', 'zhuvcuh', 'dzayv', 'ghhayud']

print("Input -> Output pairs:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"'{inp}' -> '{outp}'")

print("\nAnalyzing differences:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"'{inp}' vs '{outp}':")
    if inp != outp:
        print(f"  Length diff: {len(outp) - len(inp)}")
        # Show which characters differ
        min_len = min(len(inp), len(outp))
        for j in range(min_len):
            if inp[j] != outp[j]:
                print(f"  Position {j}: '{inp[j]}' -> '{outp[j]}'")
        if len(inp) > len(outp):
            print(f"  Removed chars at positions {len(outp)}+")
        elif len(outp) > len(inp):
            print(f"  Added chars at positions {len(inp)}+")
    else:
        print("  No difference")

